"""Writes accounts-vectors.json and src/accounts/common-passwords.ts from today's Django and allauth.

What the accounts port must reproduce (web-api spec 5.9, 5.10): the emails as allauth renders them and the
password validators' errors. Django runs with the project's settings but throwaway secrets and an example
site, so nothing of a local .env reaches the vectors; no database is touched.

Run from cloudflare/:
  MINERVA_SECRET_KEY=x MINERVA_ENCRYPTION_KEYS=v1:AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8= \
  MINERVA_SITE_URL=https://app.example.com ../backend/.venv/bin/python -I test/fixtures/accounts-vectors.py
"""

import gzip
import json
import os
import sys
from pathlib import Path
from types import SimpleNamespace

HERE = Path(__file__).resolve().parent
BACKEND = HERE.parents[2] / "backend"
sys.path.insert(0, str(BACKEND))
os.environ.setdefault("DJANGO_SETTINGS_MODULE", "minerva.settings")
os.environ["MINERVA_EMAIL_FROM"] = "Minerva <noreply@app.example.com>"
os.environ["MINERVA_DEMO"] = "false"
os.environ["MINERVA_ALLOWED_HOSTS"] = "app.example.com"

import django  # noqa: E402

django.setup()

from allauth.account.adapter import get_adapter  # noqa: E402
from allauth.account.internal.flows.signup import send_unknown_account_mail  # noqa: E402
from allauth.core import context  # noqa: E402
from django.conf import settings  # noqa: E402
from django.contrib.auth import password_validation  # noqa: E402
from django.core import mail  # noqa: E402
from django.core.exceptions import ValidationError  # noqa: E402
from django.test import RequestFactory  # noqa: E402

from accounts.models import User  # noqa: E402

settings.MAILERS = {"default": {"BACKEND": "django.core.mail.backends.locmem.EmailBackend", "OPTIONS": {}}}
CODE = "123456"
ADDRESS = "ada@example.com"


def emails() -> dict:
    request = RequestFactory().get("/", HTTP_HOST="app.example.com")
    user = User(email=ADDRESS)
    out = {}
    with context.request_context(request):
        adapter = get_adapter(request)
        confirmation = SimpleNamespace(email_address=SimpleNamespace(user=user, email=ADDRESS), key=CODE)
        sends = {
            "verify_signup": lambda: adapter.send_confirmation_mail(request, confirmation, signup=True),
            "verify_login": lambda: adapter.send_confirmation_mail(request, confirmation, signup=False),
            "already_exists": lambda: adapter.send_account_already_exists_mail(ADDRESS),
            "login_code": lambda: adapter.send_mail("account/email/login_code", ADDRESS, {"request": request, "code": CODE}),
            "unknown_account": lambda: send_unknown_account_mail(request, ADDRESS),
            "password_reset_code": lambda: adapter.send_mail(
                "account/email/password_reset_code", ADDRESS, {"request": request, "code": CODE, "user": user}
            ),
        }
        for name, send in sends.items():
            mail.outbox = []
            send()
            assert len(mail.outbox) == 1, name
            [message] = mail.outbox
            assert not message.alternatives, name
            out[name] = {"subject": message.subject, "body": message.body, "from": message.from_email, "to": message.to}
    return out


PASSWORDS = [
    "", "short", "password", "123456789", "1234567890", "12345678901", "abcdefghij", "a" * 9, "a" * 10,
    "correct horse battery staple", "Password1234", "PASSWORD1234", "  password  ", "password1234",
    "iloveyou12", "qwertyuiop", "١٢٣٤٥٦٧٨٩٠", "²²²²²²²²²²", "ada@example.com", "adaexample", "Ada Lovelace!",
    "example.com1", "ada@example.comx", "lovelace-ada-1815", "éééééééééé",
    "\U0001f600" * 9, "\U0001f600" * 10, "zxcvbnm,./", "trustno1trustno1",
]


def errors(error: ValidationError) -> list:
    return [{"message": str(item.message % item.params if item.params else item.message), "code": item.code} for item in error.error_list]


def password_vectors() -> list:
    out = []
    for password in PASSWORDS:
        row = {"password": password}
        try:
            get_adapter().clean_password(password)
            row["signup"] = []
        except ValidationError as error:
            row["signup"] = errors(error)
        try:
            password_validation.validate_password(password, User(email=ADDRESS))
            row["with_user"] = []
        except ValidationError as error:
            row["with_user"] = errors(error)
        out.append(row)
    return out


def common_passwords() -> None:
    path = Path(password_validation.__file__).parent / "common-passwords.txt.gz"
    with gzip.open(path, "rt", encoding="utf-8") as f:
        words = sorted({line.strip() for line in f})
    target = HERE.parents[1] / "src" / "accounts" / "common-passwords.ts"
    target.write_text(
        "// Generated by test/fixtures/accounts-vectors.py from Django's common-passwords.txt.gz (Django is\n"
        "// BSD-3-Clause; the list is Royce Williams's, as Django ships it): the passwords CommonPasswordValidator\n"
        "// refuses, lowercased and stripped, one per line. Do not edit.\n\n"
        f"export const COMMON_PASSWORDS: string = {json.dumps(chr(10).join(words))};\n"
    )


def main() -> None:
    common_passwords()
    out = {"site": {"url": "https://app.example.com", "from": os.environ["MINERVA_EMAIL_FROM"]}, "code": CODE, "address": ADDRESS}
    out["emails"] = emails()
    out["passwords"] = password_vectors()
    (HERE / "accounts-vectors.json").write_text(json.dumps(out, indent=1, ensure_ascii=True) + "\n")


main()
